import json
from pathlib import Path


def load_payload(path):
    """Read a UTF-8 JSON payload; top-level object or array is legal.

    Illegal JSON and top-level null/bool/number/string all raise ValueError.
    Business field validation is left to transform.
    """
    p = Path(path)
    try:
        text = p.read_text(encoding="utf-8")
    except OSError as exc:
        raise ValueError("cannot read payload: %s" % p) from exc
    try:
        obj = json.loads(text)
    except ValueError as exc:
        raise ValueError("invalid JSON: %s" % p) from exc
    if isinstance(obj, bool) or obj is None or not isinstance(obj, (dict, list)):
        raise ValueError("top-level must be object or array: %s" % p)
    return obj

