        raise ValueError("input must contain a spans field")
    spans = data["spans"]
    if not isinstance(spans, list):
        raise ValueError("spans must be a list")

    nodes = {}

    def expand(span, inherited_parent):
        if not isinstance(span, dict):
            raise ValueError("span must be an object")

        if "id" not in span:
            raise ValueError("span missing id")
        sid = span["id"]
        if not isinstance(sid, str) or not sid.strip():
            raise ValueError("span id must be a non-empty string")
        sid = sid.strip()

        if "service" not in span:
            raise ValueError("span missing service")
        service = span["service"]
        if not isinstance(service, str) or not service.strip():
            raise ValueError("span service must be a non-empty string")
        service = service.strip().lower()

        if "duration" not in span:
            raise ValueError("span missing duration")
        duration = span["duration"]
        if not _is_number(duration) or duration < 0:
            raise ValueError("duration must be a non-negative finite number")

        if "error" not in span:
            raise ValueError("span missing error")
        error = span["error"]
        if not isinstance(error, bool):
            raise ValueError("error must be a bool")

