        if sid in nodes:
            raise ValueError("duplicate span id %r" % sid)
        nodes[sid] = {
            "id": sid,
            "service": service,
            "duration": duration,
            "error": error,
            "parent": parent,
        }

        if "children" in span:
            children = span["children"]
            if not isinstance(children, list):
                raise ValueError("children must be a list of spans")
            for child in children:
                expand(child, sid)

    for span in spans:
        expand(span, None)

    # Validate parent references and detect self-loops / cycles.
    for sid, node in nodes.items():
        parent = node["parent"]
        if parent is not None:
            if parent not in nodes:
                raise ValueError("unknown parent %r" % parent)
            if parent == sid:
                raise ValueError("self-loop at span %r" % sid)

    WHITE, GRAY, BLACK = 0, 1, 2
    color = {sid: WHITE for sid in nodes}

    def dfs(sid):
        color[sid] = GRAY
        parent = nodes[sid]["parent"]
        if parent is not None:
            if color[parent] == GRAY:
                raise ValueError("cycle detected at span %r" % sid)
