    for sid in nodes:
        if color[sid] == WHITE:
            dfs(sid)

    # Root-to-node path and its total duration.
    path_cache = {}
    length_cache = {}

    def path_of(sid):
        if sid in path_cache:
            return path_cache[sid]
        parent = nodes[sid]["parent"]
        if parent is None:
            path = [sid]
        else:
            path = path_of(parent) + [sid]
        path_cache[sid] = path
        return path

    def length_of(sid):
        if sid in length_cache:
            return length_cache[sid]
        parent = nodes[sid]["parent"]
        base = nodes[sid]["duration"]
        length = base if parent is None else length_of(parent) + base
        length_cache[sid] = length
        return length

    if not nodes:
        duration = 0
        critical_path = []
    else:
        duration = None
        critical_path = None
        for sid in nodes:
            length = length_of(sid)
            path = path_of(sid)
            if duration is None or length > duration or (length == duration and path < critical_path):
                duration = length
                critical_path = path

    error_services = sorted({nodes[sid]["service"] for sid in nodes if nodes[sid]["error"]})

    return {
        "name": contract["name"],
        "result": {
            "error_services": error_services,
            "critical_path": critical_path,
            "duration": duration,
            "span_count": len(nodes),
        },
    }

